const $=s=>document.querySelector(s), escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brands={tecas:{name:'TECAS',title:'Maquinarias',intro:'Repuestos, electrónica y componentes de distintas marcas para mantener tus equipos operativos.',categories:['Partes de control remoto','Insumos y repuestos variados','Componentes electrónicos'],codes:['TCS-CR01','TCS-RP12','TCS-EL04'],counts:[40,11,6],image:'p22'},dch:{name:'DCH',title:'Radiocontroles',intro:'Sistemas de control remoto para operar maquinaria con precisión y seguridad.',categories:['Transmisor de mano','Transmisor con correa para el hombro','Transmisor de pantalla con correa para el hombro','Receptor de salida de relé','Receptor de protocolo de bus','Piezas de repuesto'],codes:['DCH-H31','DCH-S22','DCH-S23','DCH-R10','DCH-R11','DCH-P01'],counts:[16,7,5,6,6,6],image:'p25'}};
const sectors=['Puente grúa','Construcción','Oruga','Camión grúa','Torre grúa','Agricultura','Minería y petrolero'];
const applications={tecas:[['Robot Shotcrete Alpha 20','p5-1.webp',['Construcción','Minería y petrolero']],['Grúas pórtico','p5-2.webp',['Puente grúa']],['Camión grúa','p5-4.webp',['Construcción','Camión grúa']],['Radiocontroles Hetronic','p5-3.webp',['Puente grúa','Construcción','Camión grúa','Minería y petrolero']]],dch:[['Grúa monorraíl','p11-0.webp',['Puente grúa']],['Grúa polipasto CD','p11-1.webp',['Puente grúa']],['Grúa de polipasto MD','p11-2.webp',['Puente grúa']],['Grúa de doble viga','p11-3.webp',['Puente grúa']],['Grúa de gran tonelaje','p11-4.webp',['Puente grúa']],['Grúa inteligente','p11-5.webp',['Puente grúa']],['Vehículos especiales','p11-6.webp',['Construcción','Minería y petrolero']],['Equipos eléctricos','p11-7.webp',['Construcción','Minería y petrolero']],['Maquinaria para túneles','p11-8.webp',['Construcción','Oruga','Minería y petrolero']],['Bomba de hormigón','p11-9.webp',['Construcción']],['Bomba de remolque','p12-0.webp',['Construcción']],['Carro de pulverización húmeda','p12-1.webp',['Construcción']],['Maquinaria agrícola','p12-2.webp',['Oruga','Agricultura']],['Vehículos de ingeniería','p12-3.webp',['Construcción','Camión grúa']],['Extinción de incendios municipal','p12-4.webp',['Oruga']],['Maquinaria portuaria','p12-5.webp',['Minería y petrolero']],['Otros equipos','p12-6.webp',['Construcción','Torre grúa']]]};
const services={tecas:[['Reparación de tableros eléctricos','p32-0.webp'],['Reparación de equipos Putzmeister','p32-1.webp'],['Reparación de equipos Alpha 20 / Alpha 30','p32-2.webp'],['Reparación de control remoto IMET','p32-3.webp'],['Reparación de control remoto Hetronic','p32-4.webp']],dch:[['Mantenimiento y reparación de maquinarias pesadas','p34-1.webp'],['Mantenimiento de radiocontroles remoto de maquinaria pesada','p34-2.webp']]};
const company={tecas:{title:'TECAS MAQUINARIAS S.A.C.',intro:'Empresa peruana dedicada a la importación, comercialización y venta de servicios para Minería, Energía y Construcción, con amplio stock de repuestos.',mission:'Importar, comercializar y brindar servicios de mantenimiento para equipos de Minería, Energía y Construcción, con un amplio stock de repuestos que garantice la operatividad y confiabilidad de la maquinaria de nuestros clientes.',vision:'Ser la empresa peruana líder en importación y comercialización de maquinaria y repuestos para Minería, Energía y Construcción, reconocida por la disponibilidad de stock y la confiabilidad de sus equipos.',values:['Confiabilidad','Disponibilidad','Compromiso','Calidad de servicio']},dch:{title:'DCH',intro:'Radiocontrol y tecnología para maquinaria. Sistemas de radiocontrol industrial con soporte técnico especializado en controles y tableros.',mission:'Desarrollar e implementar sistemas de radiocontrol y tecnología para maquinaria industrial, brindando soporte técnico especializado en controles y tableros que optimice la operación de nuestros clientes.',vision:'Ser el referente en tecnología de radiocontrol para maquinaria industrial en el Perú, destacando por la innovación y la especialización técnica de nuestro equipo.',values:['Innovación','Especialización técnica','Soporte cercano','Precisión']}};
const photo=(src,alt,cls='')=>`<img class="${cls}" src="assets/${src}" alt="${escapeHtml(alt)}" loading="lazy">`;
const switcher=(section,brand)=>`<div class="switch" aria-label="Elegir marca"><a href="#${section}/tecas" class="${brand==='tecas'?'active':''}">TECAS</a><a href="#${section}/dch" class="${brand==='dch'?'active':''}">DCH</a></div>`;
const card=(row,brand,section,index)=>`<a class="app-card" href="#detalle/${section}/${brand}/${index}">${photo(row[1],row[0])}<div class="body"><h3>${row[0].toUpperCase()}</h3><span>Más información →</span></div></a>`;
function home(){return `<section class="hero"><h1>Control y soluciones para tu maquinaria pesada</h1><p>Una sola puerta de entrada a dos especialidades: radiocontroles DCH para operar el equipo, y repuestos y componentes TECAS para mantenerlo funcionando.</p><div class="brand-cards"><article class="brand-card"><div class="brand-logo">${photo('p2-1.webp','TECAS Maquinarias')}</div><div class="brand-copy"><div class="eyebrow">Maquinarias TECAS</div><h2>Componentes y electrónica<br>para tus equipos</h2><p>Dedicada a la importación, comercialización y venta de servicios para actividades de Minería, Energía y Construcción. Con un amplio stock de repuestos, con el fin de mantener sus equipos óptimos y confiables.</p><a class="text-link" href="#aplicaciones/tecas">Ver aplicaciones →</a></div></article><article class="brand-card"><div class="brand-logo">${photo('p2-2.webp','DCH')}</div><div class="brand-copy"><div class="eyebrow">Radiocontroles DCH</div><h2>Control remoto para<br>maquinaria industrial</h2><p>Botonera, PWM/Danfoss y control ON/OFF digital para puente grúa, torre grúa, camión grúa y más.</p><a class="text-link" href="#aplicaciones/dch">Ver aplicaciones →</a></div></article></div></section>`}
function about(brand){const c=company[brand];return `<section class="wrap ${brand}"><div class="section-head"><p class="eyebrow">Nosotros · ${brands[brand].name}</p>${switcher('nosotros',brand)}</div><div class="about"><aside class="about-aside"><h1>${c.title}</h1><p>${c.intro}</p></aside><div class="mv">${[['M','Misión',c.mission],['V','Visión',c.vision]].map(r=>`<article><span class="initial">${r[0]}</span><div><h2>${r[1].toUpperCase()}</h2><p>${r[2]}</p></div></article>`).join('')}<article><span class="initial">V</span><div><h2>VALORES</h2><div class="values">${c.values.map(v=>`<span>${v}</span>`).join('')}</div></div></article></div></div></section>`}
function apps(brand){const options=brand==='tecas'?sectors.filter(s=>!['Oruga','Torre grúa','Agricultura'].includes(s)):sectors;return `<section class="wrap ${brand}"><div class="section-head"><div><p class="eyebrow">Aplicaciones</p><h1>${brand==='tecas'?'Solución':'Un control'} por cada tipo de operación <span class="accent">— ${brands[brand].name}</span></h1></div>${switcher('aplicaciones',brand)}</div><div class="filters" aria-label="Filtrar por operación"><button class="active" data-sector="Todos" aria-pressed="true">Todos</button>${options.map(s=>`<button data-sector="${s}" aria-pressed="false">${s.toUpperCase()}</button>`).join('')}</div><div class="app-grid ${brand==='tecas'?'tecas-grid':''}" id="application-grid"></div></section>`}
function paintApps(brand,sector='Todos'){$('#application-grid').innerHTML=applications[brand].map((r,i)=>({r,i})).filter(({r})=>sector==='Todos'||r[2].includes(sector)).map(({r,i})=>card(r,brand,'aplicaciones',i)).join('')+(brand==='tecas'&&sector==='Todos'?'<div class="quote">“SOLUCIONES ESPECIALIZADAS PARA MANTENER TUS EQUIPOS OPERATIVOS Y FUNCIONANDO AL MÁXIMO.”</div>':'');document.querySelectorAll('[data-sector]').forEach(b=>{const active=b.dataset.sector===sector;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)})}
let catalogState={category:0,page:1,query:''};
function catalog(brand){if(!brand)return `<section class="wrap"><p class="eyebrow">Productos</p><h1>Dos catálogos, un solo lugar</h1><div class="catalog-choice"><a href="#productos/tecas"><h2>TECAS</h2><p>Componentes y electrónica para tus equipos</p><span>Ver TECAS →</span></a><a href="#productos/dch"><h2>DCH</h2><p>Control remoto para maquinaria industrial</p><span>Ver DCH →</span></a></div></section>`;const b=brands[brand];return `<section class="wrap ${brand}"><div class="section-head"><p class="eyebrow">Productos</p>${switcher('productos',brand)}</div><div class="catalog-head"><div class="catalog-top"><div><h1 style="font-size:24px;margin-bottom:5px">${b.name} — ${b.title}</h1><p>${b.intro}</p></div><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Buscar en esta categoría" placeholder="Buscar en esta categoría"></label></div><div class="categories">${b.categories.map((c,i)=>`<button class="category ${i===0?'active':''}" data-category="${i}" aria-pressed="${i===0}">${photo(b.image+'-'+i+'.webp',c)}<span>${b.name} · ${b.codes[i]}</span><strong>${c}</strong></button>`).join('')}</div></div><h2 class="bar-title" id="category-title"></h2><p class="count" id="count" aria-live="polite"></p><div class="product-grid" id="products-grid"></div><nav class="pagination" id="pagination" aria-label="Páginas del catálogo"></nav></section>`}
function paintCatalog(brand){const b=brands[brand],{category:c,page,query}=catalogState;const title=b.categories[c];$('#category-title').innerHTML=`${title} — <span class="accent">${b.name}</span>`;const rows=Array.from({length:b.counts[c]},(_,i)=>({i,title:brand==='tecas'&&c===0?'Transmisor de mano':title,code:brand==='tecas'?'TECAS-TCS CR02':b.codes[c]})).filter(r=>(r.title+' '+r.code+' '+(r.i+1)).toLowerCase().includes(query.toLowerCase()));const start=(page-1)*6,visible=rows.slice(start,start+6);$('#count').textContent=rows.length?`Mostrando ${start+1}–${Math.min(start+6,rows.length)} de ${rows.length} resultados`:'No hay resultados para esta búsqueda.';$('#products-grid').innerHTML=visible.map(r=>`<article class="product-card">${photo(b.image+'-'+c+'.webp',r.title,'catalog-product-image')}<div class="product-body"><span class="code">${r.code}</span><h3>${r.title}</h3><p>${productDescriptions[brand][c][4]}</p><a class="more" href="#detalle/productos/${brand}/${c}/${r.i}">Más +<span class="sr-only" hidden> Ver producto</span></a></div></article>`).join('')||'<div class="empty">Prueba con otro nombre o referencia.</div>';$('#pagination').innerHTML=Array.from({length:Math.ceil(rows.length/6)},(_,i)=>`<button data-page="${i+1}" class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('');document.querySelectorAll('[data-category]').forEach(el=>{el.classList.toggle('active',+el.dataset.category===c);el.setAttribute('aria-pressed',+el.dataset.category===c)})}
function solutions(){return `<section class="solutions"><p class="eyebrow">Soluciones</p><h2>De la idea a la maquinaria en operación</h2><p class="lead">Además de vender producto, se desarrolla la solución completa cuando el equipo lo requiere.</p><div class="solution-grid">${[['Fabricación','Fabricación a medida','Producción de componentes y sistemas específicos para el equipo.'],['Diseño','Diseño de sistemas','Diseño de tableros y soluciones de control adaptadas a la operación.'],['Importación','Importación directa','Abastecimiento de repuestos y componentes desde marcas originales.'],['Integración','Integración en planta','Adaptación e instalación del sistema de control en la maquinaria.']].map(r=>`<article><span>${r[0].toUpperCase()}</span><h3>${r[1]}</h3><p>${r[2]}</p></article>`).join('')}</div>${photo('p36-0.webp','Componentes y sistemas para maquinaria industrial','solution-banner')}</section>`}
function servicePage(brand){return `<section class="wrap ${brand}"><div class="section-head"><div><p class="eyebrow">Servicios</p><h1>${brand==='tecas'?'Mantenemos tu operación en movimiento.':'Precisión, tecnología y respaldo para tu maquinaria.'} <span class="accent">— ${brands[brand].name}</span></h1></div>${switcher('servicios',brand)}</div><div class="services-grid ${brand==='dch'?'dch-services':''}">${services[brand].map((r,i)=>card(r,brand,'servicios',i)).join('')}${brand==='tecas'?'<div class="quote">“SOLUCIONES ESPECIALIZADAS PARA MANTENER TUS EQUIPOS OPERATIVOS Y FUNCIONANDO AL MÁXIMO.”</div>':''}</div>${solutions()}</section>`}
function support(){return `<section class="support"><div class="support-copy"><p class="eyebrow">Soporte</p><h1>Soporte técnico especializado en controles, tableros y otros</h1><p>Un mismo equipo técnico atiende tanto los radiocontroles DCH como los repuestos y tableros TECAS.</p><div class="support-tags">${['Diagnóstico','Reparación','Mantenimiento','Repuestos','Soporte para controles','Soporte para tableros'].map(s=>`<span>${s}</span>`).join('')}</div><a href="#contacto" class="primary" style="margin-top:35px">Solicitar soporte →</a></div>${photo('p37-0.webp','Técnico revisando un tablero de control')}</section>`}
function contact(){return `<section class="contact"><div><p class="eyebrow">Contacto</p><h1>¿Necesitas una solución para tu maquinaria?</h1><p>Escríbenos y te ayudamos a identificar el radiocontrol o repuesto correcto para tu equipo.</p><div class="contact-block"><h3>DCH</h3><strong>DCH RADIO LIMITED COMPANY</strong><br>Teléfono móvil: (+51) 916 024 169<br><a href="mailto:vasquezmendez95@gmail.com">vasquezmendez95@gmail.com</a></div><div class="contact-block"><h3>TECAS</h3><strong>TECAS MAQUINARIAS S.A.C.</strong><br><a href="tel:+51916024169">Teléfono móvil: (+51) 916 024 169</a><br><a href="mailto:vasquezmendez95@gmail.com">vasquezmendez95@gmail.com</a></div><div class="contact-block"><h3>Ubicación</h3>Lima, Perú</div></div><form id="contact-form"><label>Nombre y empresa<input name="name" required autocomplete="organization" placeholder="Tu nombre y empresa"></label><label>Correo electrónico<input name="email" type="email" required autocomplete="email" placeholder="nombre@empresa.com"></label><label>Equipo o aplicación (opcional)<input name="equipment" placeholder="Ej. puente grúa"></label><label>Cuéntanos qué necesitas<textarea name="message" required placeholder="Describe tu consulta"></textarea></label><button class="primary" type="submit">Enviar consulta</button><p class="form-result" role="status"></p></form></section>`}
function detail(section,brand,index){
 const isProduct=section==='productos',list=section==='servicios'?services[brand]:applications[brand];
 if(!['productos','servicios','aplicaciones'].includes(section)||!Number.isInteger(index)||index<0)return notFound();
 const row=isProduct?null:list[index];if((!isProduct&&!row)||(isProduct&&!brands[brand].categories[index]))return notFound();
 const title=isProduct?brands[brand].categories[index]:row[0];
 const content=detailContent(section,brand,index,title);
 const src=isProduct?brands[brand].image+'-'+index+'.webp':row[1];
 return `<section class="wrap ${brand}"><div class="detail-top"><h1>${title}</h1><div class="breadcrumb"><a href="#inicio">Inicio</a> / <a href="#${section}/${brand}">${section[0].toUpperCase()+section.slice(1)}</a> / ${brands[brand].name}</div></div><div class="detail"><div>${photo(src,title,'detail-image'+(isProduct?' category-image':''))}<a class="text-link" href="#${section}/${brand}">← Volver a ${section}</a></div><div><p class="eyebrow">${brands[brand].name}${isProduct?' · '+brands[brand].codes[index]:''}</p><h2>${title}</h2><p class="detail-description">${content.description}</p><dl class="specs">${content.rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><a href="#contacto" class="primary" style="margin-top:28px">Consultar por ${section==='servicios'?'este servicio':'esta solución'} →</a></div></div></section>`;
}
function notFound(){return '<section class="wrap"><h1>Página no encontrada</h1><a class="primary" href="#inicio">Volver al inicio</a></section>'}
let specsCache;
function render(){const route=location.hash.slice(1).split('/'),section=route[0]||'inicio',brand=route[1]==='dch'?'dch':'tecas';catalogState={category:0,page:1,query:''};let html;switch(section){case'inicio':html=home();break;case'nosotros':html=about(brand);break;case'aplicaciones':html=apps(brand);break;case'productos':html=catalog(route[1]?brand:null);break;case'servicios':html=servicePage(brand);break;case'soporte':html=support();break;case'contacto':html=contact();break;case'detalle':html=detail(route[1],route[2]==='dch'?'dch':'tecas',Number(route[3])||0);break;default:html=notFound()}
$('#content').innerHTML=html;document.title=`${section==='inicio'?'Maquinaria y radiocontroles':section.charAt(0).toUpperCase()+section.slice(1)} | TECAS · DCH`;
$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('#navigation a').forEach(a=>{if(a.hash.split('/')[0]==='#'+(section==='detalle'?route[1]:section))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
if(section==='aplicaciones'){paintApps(brand);document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>paintApps(brand,b.dataset.sector))}
if(section==='productos'&&route[1]){paintCatalog(brand);$('.categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){catalogState.category=+b.dataset.category;catalogState.page=1;catalogState.query='';$('#search').value='';paintCatalog(brand)}};$('#search').oninput=e=>{catalogState.query=e.target.value;catalogState.page=1;paintCatalog(brand)};$('#pagination').onclick=e=>{const b=e.target.closest('[data-page]');if(b){catalogState.page=+b.dataset.page;paintCatalog(brand);$('#category-title').scrollIntoView({block:'start'})}}}
if(section==='contacto')$('#contact-form').onsubmit=e=>{e.preventDefault();$('.form-result').textContent='El envío desde este formulario no está disponible. Puedes contactarnos por correo o WhatsApp.'};
if($('#specs')){const target=$('#specs');(specsCache?Promise.resolve(specsCache):fetch('specs.json').then(r=>r.json()).then(s=>specsCache=s)).then(rows=>{if(target.isConnected)target.innerHTML=rows.map(([k,v])=>`<div><dt>${escapeHtml(k)}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}).catch(()=>{target.innerHTML='<div><dt>Ficha técnica</dt><dd>Información temporalmente no disponible.</dd></div>'})}
window.scrollTo(0,0);}
$('.skip').onclick=e=>{e.preventDefault();$('#content').focus();};$('.menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)};window.addEventListener('hashchange',()=>{render();$('#content').focus({preventScroll:true})});render();
